window.AUTH=window.AUTH||{};window.AUTH["12-1315"]={"d":"12-1315","id":"2013/12-1315","n":"Petrella v. MGM, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting petitioner","date":"2013-11-22","url":"https://www.justice.gov/osg/media/206916/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/petrella-v-metro-goldwyn-mayer-inc-amicus-merits","n":77}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep572/usrep572663/usrep572663.pdf","tr":true,"items":[{"t":"case","label":"A.C. Aukerman Co. v. R.L. Chaides Constr. Co.","cite":"960 F.2d 1020","y":1992,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/960/1020/","op":2,"by":{"0":"25"}},{"t":"case","label":"Alsop v. Riker","cite":"155 U.S. 448","y":1894,"id":"scdb/1894-048","sc":1,"op":1,"sum":"Holding that “independently of the statute of limitations,” the contract action was barred “because of laches”.","sumSrc":"opinion","by":{"0":"22, 26"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"op":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Badger v. Badger","cite":"69 U.S. 87","y":1865,"id":"scdb/1864-021","sc":1,"sum":"Courts of equity, acting on their own inherent doctrine of discouraging, for the peace of society, antiquated demands, refuse to interfere in attempts to.establish a stale trust, except where,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Trust Fund v. Ferbar Corp. of Cal.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"op":5,"ar":4,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Bouchat v. Baltimore Ravens Ltd. P’ship","cite":"619 F.3d 301","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/619/301/","by":{"0":"12"}},{"t":"case","label":"Bowman v. Wathen","cite":"42 U.S. 189","y":1843,"id":"scdb/1843-021","sc":1,"sum":"The doctrine laid downby Lord Camden, in the case of Smith v. Clay, 3 Brown's-Oh. Rep. in note,-examined and confirmed,-vis., “That a court'Of equity, which never is active in-relief against conscience' or'public convenience has'always refused its aid to stale demands, where the party has slept upon, his rights for a great length of time. Nothing can call forth this court into activity but. conscience, good faith, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Bridgeport Music, Inc. v. Rhyme Syndicate Music","cite":"376 F.3d 615","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/615/","op":1,"by":{"0":"13"}},{"t":"case","label":"Callaghan v. Myers","cite":"128 U.S. 617","y":1888,"id":"scdb/1888-073","sc":1,"op":1,"sum":"Although there can be no copyright in the opinions of the judges of a court, or in the work done by them in their official capacity as judges, there is no ground of public policy on which a reporter, who prepares a volume of law reports, of the usual character, can be debarred from obtaining a copyright for the volume, which will cover the mattenwhich is the result of his intellectual labor.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Chesapeake & Del. Canal Co. v. United States","cite":"250 U.S. 123","y":1919,"id":"scdb/1918-058","sc":1,"sum":"It is a perversion of the rule requiring assignments of error to multiply them unnecessarily.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Chirco v. Crosswinds Cmtys., Inc.","cite":"474 F.3d 227","y":2007,"url":"https://www.courtlistener.com/c/F.3d/474/227/","op":8,"ar":1,"sum":"Describing National Railroad Passenger Corporation v. Morgan, 536 U. S. 101 (2002).","sumSrc":"opinion","by":{"0":"16, 27"}},{"t":"case","label":"Costello v. United States","cite":"365 U.S. 265","y":1961,"id":"1960/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"County of Oneida, N.Y. v. Oneida Indian Nation","cite":"470 U.S. 226","y":1985,"id":"1984/83-1065","sc":1,"op":7,"ar":2,"sum":"Respondent Indian Tribes (hereafter respondents) brought an action in Federal District Court against petitioner counties (hereafter petitioners), alleging that respondents' ancestors conveyed tribal land to New York State, under a 1795 agreement that violated the Nonintercourse Act of 1793-which provided that no person or entity could purchase Indian land without the Federal Government's approval-and that thus the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 27"}},{"t":"case","label":"D.O. Haynes & Co. v. Druggists’ Circular","cite":"32 F.2d 215","y":1929,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/32/215/","op":1,"by":{"0":"23"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Edwin L. Wiegand Co. v. Harold E. Trent Co.","cite":"122 F.2d 920","y":1941,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.2d/122/920/","op":1,"by":{"0":"23"}},{"t":"case","label":"Environmental Def. Fund, Inc. v. Alexander","cite":"614 F.2d 474","y":1980,"url":"https://www.courtlistener.com/c/F.2d/614/474/","by":{"0":"22, 27"}},{"t":"case","label":"Gabelli v. SEC","cite":"133 S. Ct. 1216","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./133/1216/","sc":1,"by":{"0":"11"}},{"t":"case","label":"Galliher v. Cadwell","cite":"145 U.S. 368","y":1892,"id":"scdb/1891-239","sc":1,"op":1,"sum":"Laches does no.t, like limitation, grow out of the mere passage of time; but it is founded upon the inequity of permitting the claim to be enforced— an inequity founded upop some change in the conditioiror relations of- - the property or the parties.'","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Godden v. Kimmell","cite":"99 U.S. 201","y":1879,"id":"scdb/1878-174","sc":1,"by":{"0":"22, 26"}},{"t":"case","label":"Grand Canyon Trust v. Tucson Elec. Power Co.","cite":"391 F.3d 979","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/391/979/","by":{"0":"5"}},{"t":"case","label":"Guaranty Trust Co. v. United States","cite":"304 U.S. 126","y":1938,"id":"scdb/1937-044","sc":1,"sum":"1. The rule which exempts the United States and the States from the operation of statutes of limitations rests not upon any inherited notion of royal prerogative but upon the public policy of protecting the public rights, and thereby the citizen, from injury through negligence of public officers.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Haas v. Leo Feist, Inc.","cite":"234 F. 105","y":1916,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./234/105/","op":4,"ar":1,"by":{"0":"24"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"op":6,"ar":7,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 23"}},{"t":"case","label":"Hoste v. Radio Corp. of Am.","cite":"654 F.2d 11","y":1981,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/654/11/","by":{"0":"16"}},{"t":"case","label":"Ivani Contracting Corp. v. City of N.Y.","cite":"103 F.3d 257","y":1997,"url":"https://www.courtlistener.com/c/F.3d/103/257/","by":{"0":"21, 27"}},{"t":"case","label":"Johnson v. Railway Express Agency, Inc.","cite":"421 U.S. 454","y":1975,"id":"1974/73-1543","sc":1,"op":1,"sum":"The timely filing of an employment discrimination charge with the Equal Employment Opportunity Commission, pursuant to § 706 of Title VII of the Civil Rights Act of 1964, does not toll the running of the limitation period applicable to an action, based on the same facts, brought under 42 U. S. C. § 1981. Thus, in this case where petitioner waited over 31/2 years after his cause of action for racial employment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Klehr v. A.O. Smith Corp.","cite":"521 U.S. 179","y":1997,"id":"1996/96-663","sc":1,"op":2,"ar":1,"sum":"No and No. Justice Stephen Breyer wrote the opinion for a unanimous Court. The \"last predicate rule...lengthens the limitations period dramatically\" and thereby contradicts Congress's intention of ensuring a time limit for civil RICO claims.","sumSrc":"Oyez","by":{"0":"13, 14"}},{"t":"case","label":"Lane & Bodley Co. v. Locke","cite":"150 U.S. 193","y":1893,"id":"scdb/1893-033","sc":1,"sum":"In 1871 L. & B., being partners, commenced tlie manufacture of hydraulic elevators in Cincinnati. S-. was employed by them as engineer and draughtsman at a fixed salary of-ü>1200 per annum. While in their employ, and while using their tools and patterns, he invented a stop-valve in 1872, which was patented In February, 1870. In 1876 the partnership was dissolved, and a corporation was formed, called the L. & B. …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Lyons P’ship, L.P. v. Morris Costumes, Inc.","cite":"243 F.3d 789","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/243/789/","op":2,"by":{"0":"27"}},{"t":"case","label":"Mackall v. Casilear","cite":"137 U.S. 556","y":1890,"id":"scdb/1890-064","sc":1,"sum":"The plaintiff, having averred in his complaint the execution of a deed by him to his father, and having conceded its delivery, and there being no prayer for specific relief as to it, and no averments that would entitle him to have it set aside for want of acknowledgment under the prayer for general relief, he cannot set up that the deed is not operative, even as between the parties, for want of proper acknowledgment …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21, 26"}},{"t":"case","label":"Makedwde Publ’g Co. v. Johnson","cite":"37 F.3d 180","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/37/180/","op":1,"by":{"0":"13, 16"}},{"t":"case","label":"Maksym v. Loesch","cite":"937 F.2d 1237","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/937/1237/","by":{"0":"27"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"op":8,"ar":3,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Miller v. Glenn Miller Prods., Inc.","cite":"454 F.3d 975","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/454/975/","by":{"0":"6, 15"}},{"t":"case","label":"National R.R. Passenger Corp. v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"op":6,"sum":"Describing Patterson v. Hewitt, 195 U. S. 309 (1904).","sumSrc":"opinion","by":{"0":"13"}},{"t":"case","label":"New Era Publ’ns Int’l, ApS v. Henry Holt & Co.","cite":"873 F.2d 576","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/873/576/","op":4,"by":{"0":"27"}},{"t":"case","label":"New York City v. Pine","cite":"185 U.S. 93","y":1902,"id":"scdb/1901-057","sc":1,"op":1,"ar":1,"sum":"The time at which a party appeals to a court of equity for relief affects largely the character of the relief which will be granted.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Order of R.R. Telegraphers v. Railway Express Agency, Inc.","cite":"321 U.S. 342","y":1944,"id":"scdb/1943-094","sc":1,"sum":"1. Failure of the carrier to give notice, to the representative of the employees, of an intended change affecting rates of pay of certain individual employees was in violation of § 6 of the Railway Labor Act of 1926, applicable to the collective agreement in question, and rendered ineffective the individual agreements entered into; and the award of the Adjustment Board, based on the collective agreement, was in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Patterson v. Hewitt","cite":"195 U.S. 309","y":1904,"id":"scdb/1904-028","sc":1,"op":4,"ar":5,"sum":"The owners of a mining claim in New Mexico transferred their interests to one of their number as trustee, who was to retransfer to each one contributing his share of development expenses for a year, a one-eighth interest. Plaintiff, one of the parties, contributed his share and demanded a deed which the trustee refused to give. Plaintiff made no further demand and did not contribute any more to the expenses, but the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22, 26"}},{"t":"case","label":"Peter Letterese & Assocs., Inc. v. World Inst. of Scientology Enters., Int’l","cite":"533 F.3d 1287","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/533/1287/","op":5,"by":{"0":"13, 28"}},{"t":"case","label":"Rawlings v. Ray","cite":"312 U.S. 96","y":1941,"id":"scdb/1940-056","sc":1,"sum":"1. The state statute of limitations applies in an action by the receiver of an insolvent national bank against a stockholder to collect a Comptroller's assessment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Roley v. New World Pictures, Ltd.","cite":"19 F.3d 479","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/19/479/","op":1,"by":{"0":"13, 16"}},{"t":"case","label":"Russell v. Todd","cite":"309 U.S. 280","y":1940,"id":"scdb/1939-074","sc":1,"op":1,"ar":4,"sum":"1. The shareholders' liability, \"equally and ratably,\" for the debts of a joint stock land bank, under § 16 of the Federal Farm Loan Act, is enforceable only by a single representative suit in equity in behalf of all the creditors, in which the existence and extent of insolvency, and the ratable shares of the contribution by shareholders, can be ascertained and an equitable distribution made of the fund recovered. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 21, 22, 27"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"309 U.S. 390","y":1940,"id":"scdb/1939-111","sc":1,"op":1,"sum":"1. That clause of § 25 (b) of the Copyright Act which authorizes recovery from an infringer, \"in lieu of actual damages and profits,\" of \"such 'damages as to the court shall appear to be just,\" is inapplicable where the only matter in question is the apportionment of profits established.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Stewart v. Abend","cite":"495 U.S. 207","y":1990,"id":"1989/88-2102","sc":1,"op":3,"sum":"In 1945, author Cornell Woolrich agreed to assign the motion picture rights to several of his stories, including the one at issue, to petitioners' predecessor in interest. He also agreed to renew the copyrights in the stories at the appropriate time and to assign the same motion picture rights to the predecessor in interest for the 28-year renewal term provided by the Copyright Act of 1909. The film version of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"Stone v. Williams","cite":"970 F.2d 1043","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/970/1043/","op":1,"by":{"0":"12, 13"}},{"t":"case","label":"Taylor v. Meirick","cite":"712 F.2d 1112","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/712/1112/","by":{"0":"13"}},{"t":"case","label":"United States v. Beebe","cite":"127 U.S. 338","y":1888,"id":"scdb/1887-247","sc":1,"sum":"The Attorney General has authority, under the Constitution, to file a bill in equity in the name of the United States to set aside a patent of public land alleged to have been obtained by fraud or mistake, when the government has a direct interest in the tract patented, or is under an obligation respecting the relief invoked by the bill. The United States are not bound by any statute of limitations, nor barred by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"United States v. Mack","cite":"295 U.S. 480","y":1935,"id":"scdb/1934-132","sc":1,"op":2,"ar":5,"sum":"Assistant to the Attorney General Stanley, with whom Solicitor General Reed and Messrs. Alexander Holtzoff and Carl McFarland were on the brief, for the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26, 28"}},{"t":"case","label":"United States v. Verdier","cite":"164 U.S. 213","y":1896,"id":"scdb/1896-016","sc":1,"sum":"In actions In the Court of Claims interest prior to the judgment\" cannot be allowed to claimants, against the United States; but the provisions of Rev. Stat § 966 peremptorily require it to be allowed to the United States, against claimants, under all circumstances to which the statute applies, and without regard to equities which might be considered between private parties.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Werner Co. v. Encyclopaedia Britannica Co.","cite":"134 F. 831","y":1905,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F./134/831/","by":{"0":"23"}},{"t":"case","label":"West Publ’g Co. v. Edward Thompson Co.","cite":"169 F. 833","y":1909,"court":"C.C.E.D.N.Y.","url":"https://www.courtlistener.com/c/F./169/833/","by":{"0":"23"}},{"t":"case","label":"Whitney v. Fox","cite":"166 U.S. 637","y":1897,"id":"scdb/1896-169","sc":1,"sum":"It is the ordinary rule to accept the interpretation given to a statute by the courts of the country by which it was originally adopted; but the rule is not an absolute one to be followed under all circumstances. In this case the court accepts the construction given by the Supreme Court of the Territory of Utah to a statute of that Territory disqualifying certain persons as witnesses, rather than the construction …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"William A. Graham Co. v. Haughey","cite":"568 F.3d 425","y":2009,"url":"https://www.courtlistener.com/c/F.3d/568/425/","op":2,"by":{"0":"12, 13"}},{"t":"case","label":"Zenith Radio Corp. v. Hazeltine Research, Inc.","cite":"401 U.S. 321","y":1971,"id":"1970/80","sc":1,"sum":"The Supreme Court also held that damages were only proper with respect to the Canadian market because it was the only market in which Zenith had sustained injury. The Supreme Court reinstated the District Court's injunction against Hazeltine's conspiracy to restrict trade in foreign markets.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"usc","label":"17 U.S.C. § 115","url":"https://www.law.cornell.edu/uscode/text/17/115","subs":["(b)(1958)"],"stext":{"head":"§115. Scope of exclusive rights in nondramatic musical works: Compulsory license for making and distributing phonorecords","paras":[[0,"In the case of nondramatic musical works, the exclusive rights provided by clauses (1) and (3) of section 106, to make and to distribute phonorecords of such works, are subject to compulsory licensing under the conditions specified by this section."],[0,"(a) Availability and Scope of Compulsory License in General.—"],[1,"(1) Eligibility for compulsory license.—"],[2,"(A) Conditions for compulsory license.—A person may by complying with the provisions of this section obtain a compulsory license to make and distribute phonorecords of a nondramatic musical work, including by means of digital phonorecord delivery. A person may obtain a compulsory license only if the primary purpose in making phonorecords of the musical work is to distribute them to the public for private use, including by means of digital phonorecord delivery, and—"],[3,"(i) phonorecords of such musical work have previously been distributed to the public in the United States under the authority of the copyright owner of the work, including by means of digital phonorecord delivery; or"],[3,"(ii) in the case of a digital music provider seeking to make and distribute digital phonorecord deliveries of a sound recording embodying a musical work under a compulsory license for which clause (i) does not apply—"],[4,"(I) the first fixation of such sound recording was made under the authority of the musical work copyright owner, and the sound recording copyright owner has the authority of the musical work copyright owner to make and distribute digital phonorecord deliveries embodying such work to the public in the United States; and"],[4,"(II) the sound recording copyright owner, or the authorized distributor of the sound recording copyright owner, has authorized the digital music provider to make and distribute digital phonorecord deliveries of the sound recording to the public in the United States."],[2,"(B) Duplication of sound recording.—A person may not obtain a compulsory license for the use of the work in the making of phonorecords duplicating a sound recording fixed by another, including by means of digital phonorecord delivery, unless—"],[3,"(i) such sound recording was fixed lawfully; and"],[3,"(ii) the making of the phonorecords was authorized by the owner of the copyright in the sound recording or, if the sound recording was fixed before February 15, 1972, by any person who fixed the sound recording pursuant to an express license from the owner of the copyright in the musical work or pursuant to a valid compulsory license for use of such work in a sound recording."],[1,"(2) Musical arrangement.—A compulsory license includes the privilege of making a musical arrangement of the work to the extent necessary to conform it to the style or manner of interpretation of the performance involved, but the arrangement shall not change the basic melody or fundamental character of the work, and shall not be subject to protection as a derivative work under this title, except with the express consent of the copyright owner."],[0,"(b) Procedures To Obtain a Compulsory License.—"],[1,"(1) Phonorecords other than digital phonorecord deliveries.—A person who seeks to obtain a compulsory license under subsection (a) to make and distribute phonorecords of a musical work other than by means of digital phonorecord delivery shall, before, or not later than 30 calendar days after, making, and before distributing, any phonorecord of the work, serve notice of intention to do so on the copyright owner. If the registration or other public records of the Copyright Office do not identify the copyright owner and include an address at which notice can be served, it shall be sufficient to file the notice of intention with the Copyright Office. The notice shall comply, in form, content, and manner of service, with requirements that the Register of Copyrights shall prescribe by regulation."],[1,"(2) Digital phonorecord deliveries.—A person who seeks to obtain a compulsory license under subsection (a) to make and distribute phonorecords of a musical work by means of digital phonorecord delivery—"],[2,"(A) prior to the license availability date, shall, before, or not later than 30 calendar days after, first making any such digital phonorecord delivery, serve a notice of intention to do so on the copyright owner (but may not file the notice with the Copyright Office, even if the public records of the Office do not identify the owner or the owner's address), and such notice shall comply, in form, content, and manner of service, with requirements that the Register of Copyrights shall prescribe by regulation; or"],[2,"(B) on or after the license availability date, shall, before making any such digital phonorecord delivery, follow the procedure described in subsection (d)(2), except as provided in paragraph (3)."],[1,"(3) Record company individual download licenses.—Notwithstanding paragraph (2)(B), a record company may, on or after the license availability date, obtain an individual download license in accordance with the notice requirements described in paragraph (2)(A) (except for the requirement that notice occur prior to the license availability date). A record company that obtains an individual download license as permitted under this paragraph shall provide statements of account and pay royalties as provided in subsection (c)(2)(I)."],[1,"(4) Failure to obtain license.—"],[2,"(A) Phonorecords other than digital phonorecord deliveries.—In the case of phonorecords made and distributed other than by means of digital phonorecord delivery, the failure to serve or file the notice of intention required by paragraph (1) forecloses the possibility of a compulsory license under paragraph (1). In the absence of a voluntary license, the failure to obtain a compulsory license renders the making and distribution of phonorecords actionable as acts of infringement under section 501 and subject to the remedies provided by sections 502 through 506."],[2,"(B) Digital phonorecord deliveries.—"],[3,"(i) In general.—In the case of phonorecords made and distributed by means of digital phonorecord delivery:"],[4,"(I) The failure to serve the notice of intention required by paragraph (2)(A) or paragraph (3), as applicable, forecloses the possibility of a compulsory license under such paragraph."],[4,"(II) The failure to comply with paragraph (2)(B) forecloses the possibility of a blanket license for a period of 3 years after the last calendar day on which the notice of license was required to be submitted to the mechanical licensing collective under such paragraph."],[3,"(ii) Effect of failure.—In either case described in subclause (I) or (II) of clause (i), in the absence of a voluntary license, the failure to obtain a compulsory license renders the making and distribution of phonorecords by means of digital phonorecord delivery actionable as acts of infringement under section 501 and subject to the remedies provided by sections 502 through 506."],[0,"(c) General Conditions Applicable to Compulsory License.—"],[1,"(1) Royalty payable under compulsory license.—"],[2,"(A) Identification requirement.—To be entitled to receive royalties under a compulsory license obtained under subsection (b)(1) the copyright owner must be identified in the registration or other public records of the Copyright Office. The owner is entitled to royalties for phonorecords made and distributed after being so identified, but is not entitled to recover for any phonorecords previously made and distributed."],[2,"(B) Royalty for phonorecords other than digital phonorecord deliveries.—Except as provided by subparagraph (A), for every phonorecord made and distributed under a compulsory license under subsection (a) other than by means of digital phonorecord delivery, with respect to each work embodied in the phonorecord, the royalty shall be the royalty prescribed under subparagraphs (D) through (F), paragraph (2)(A), and chapter 8. For purposes of this subparagraph, a phonorecord is considered \"distributed\" if the person exercising the compulsory license has voluntarily and permanently parted with its possession."],[2,"(C) Royalty for digital phonorecord deliveries.—For every digital phonorecord delivery of a musical work made under a compulsory license under this section, the royalty payable shall be the royalty prescribed under subparagraphs (D) through (F), paragraph (2)(A), and chapter 8."],[2,"(D) Authority to negotiate.—Notwithstanding any provision of the antitrust laws, any copyright owners of nondramatic musical works and any persons entitled to obtain a compulsory license under subsection (a) may negotiate and agree upon the terms and rates of royalty payments under this section and the proportionate division of fees paid among copyright owners, and may designate common agents on a nonexclusive basis to negotiate, agree to, pay or receive such royalty payments. Such authority to negotiate the terms and rates of royalty payments includes, but is not limited to, the authority to negotiate the year during which the royalty rates prescribed under this subparagraph, subparagraphs (E) and (F), paragraph (2)(A), and chapter 8 shall next be determined."],[2,"(E) Determination of reasonable rates and terms.—Proceedings under chapter 8 shall determine reasonable rates and terms of royalty payments for the activities specified by this section during the period beginning with the effective date of such rates and terms, but not earlier than January 1 of the second year following the year in which the petition requesting the proceeding is filed, and ending on the effective date of successor rates and terms, or such other period as the parties may agree. Any copyright owners of nondramatic musical works and any persons entitled to obtain a compulsory license under subsection (a) may submit to the Copyright Royalty Judges licenses covering such activities. The parties to each proceeding shall bear their own costs."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/115?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§115. Scope of exclusive rights in nondramatic musical works: Compulsory license for making and distributing phonorecords","tname":"Copyrights","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 94-553","url":"https://www.govinfo.gov/link/statute/90/2586","by":{"0":"11"}},{"t":"usc","label":"17 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/17/101","stext":{"head":"§101. Definitions","paras":[[0,"Except as otherwise provided in this title, as used in this title, the following terms and their variant forms mean the following:"],[1,"An \"anonymous work\" is a work on the copies or phonorecords of which no natural person is identified as author."],[1,"An \"architectural work\" is the design of a building as embodied in any tangible medium of expression, including a building, architectural plans, or drawings. The work includes the overall form as well as the arrangement and composition of spaces and elements in the design, but does not include individual standard features."],[1,"\"Audiovisual works\" are works that consist of a series of related images which are intrinsically intended to be shown by the use of machines, or devices such as projectors, viewers, or electronic equipment, together with accompanying sounds, if any, regardless of the nature of the material objects, such as films or tapes, in which the works are embodied."],[1,"The \"Berne Convention\" is the Convention for the Protection of Literary and Artistic Works, signed at Berne, Switzerland, on September 9, 1886, and all acts, protocols, and revisions thereto."],[1,"The \"best edition\" of a work is the edition, published in the United States at any time before the date of deposit, that the Library of Congress determines to be most suitable for its purposes."],[1,"A person's \"children\" are that person's immediate offspring, whether legitimate or not, and any children legally adopted by that person."],[1,"A \"collective work\" is a work, such as a periodical issue, anthology, or encyclopedia, in which a number of contributions, constituting separate and independent works in themselves, are assembled into a collective whole."],[1,"A \"compilation\" is a work formed by the collection and assembling of preexisting materials or of data that are selected, coordinated, or arranged in such a way that the resulting work as a whole constitutes an original work of authorship. The term \"compilation\" includes collective works."],[1,"A \"computer program\" is a set of statements or instructions to be used directly or indirectly in a computer in order to bring about a certain result."],[1,"\"Copies\" are material objects, other than phonorecords, in which a work is fixed by any method now known or later developed, and from which the work can be perceived, reproduced, or otherwise communicated, either directly or with the aid of a machine or device. The term \"copies\" includes the material object, other than a phonorecord, in which the work is first fixed."],[1,"\"Copyright owner\", with respect to any one of the exclusive rights comprised in a copyright, refers to the owner of that particular right."],[1,"A \"Copyright Royalty Judge\" is a Copyright Royalty Judge appointed under section 802 of this title, and includes any individual serving as an interim Copyright Royalty Judge under such section."],[1,"A work is \"created\" when it is fixed in a copy or phonorecord for the first time; where a work is prepared over a period of time, the portion of it that has been fixed at any particular time constitutes the work as of that time, and where the work has been prepared in different versions, each version constitutes a separate work."],[1,"A \"derivative work\" is a work based upon one or more preexisting works, such as a translation, musical arrangement, dramatization, fictionalization, motion picture version, sound recording, art reproduction, abridgment, condensation, or any other form in which a work may be recast, transformed, or adapted. A work consisting of editorial revisions, annotations, elaborations, or other modifications which, as a whole, represent an original work of authorship, is a \"derivative work\"."],[1,"A \"device\", \"machine\", or \"process\" is one now known or later developed."],[1,"A \"digital transmission\" is a transmission in whole or in part in a digital or other non-analog format."],[1,"To \"display\" a work means to show a copy of it, either directly or by means of a film, slide, television image, or any other device or process or, in the case of a motion picture or other audiovisual work, to show individual images nonsequentially."],[1,"An \"establishment\" is a store, shop, or any similar place of business open to the general public for the primary purpose of selling goods or services in which the majority of the gross square feet of space that is nonresidential is used for that purpose, and in which nondramatic musical works are performed publicly."],[1,"The term \"financial gain\" includes receipt, or expectation of receipt, of anything of value, including the receipt of other copyrighted works."],[1,"A work is \"fixed\" in a tangible medium of expression when its embodiment in a copy or phonorecord, by or under the authority of the author, is sufficiently permanent or stable to permit it to be perceived, reproduced, or otherwise communicated for a period of more than transitory duration. A work consisting of sounds, images, or both, that are being transmitted, is \"fixed\" for purposes of this title if a fixation of the work is being made simultaneously with its transmission."],[1,"A \"food service or drinking establishment\" is a restaurant, inn, bar, tavern, or any other similar place of business in which the public or patrons assemble for the primary purpose of being served food or drink, in which the majority of the gross square feet of space that is nonresidential is used for that purpose, and in which nondramatic musical works are performed publicly."],[1,"The \"Geneva Phonograms Convention\" is the Convention for the Protection of Producers of Phonograms Against Unauthorized Duplication of Their Phonograms, concluded at Geneva, Switzerland, on October 29, 1971."],[1,"The \"gross square feet of space\" of an establishment means the entire interior space of that establishment, and any adjoining outdoor space used to serve patrons, whether on a seasonal basis or otherwise."],[1,"The terms \"including\" and \"such as\" are illustrative and not limitative."],[1,"An \"international agreement\" is—"],[2,"(1) the Universal Copyright Convention;"],[2,"(2) the Geneva Phonograms Convention;"],[2,"(3) the Berne Convention;"],[2,"(4) the WTO Agreement;"],[2,"(5) the WIPO Copyright Treaty;"],[2,"(6) the WIPO Performances and Phonograms Treaty; and"],[2,"(7) any other copyright treaty to which the United States is a party."],[1,"A \"joint work\" is a work prepared by two or more authors with the intention that their contributions be merged into inseparable or interdependent parts of a unitary whole."],[1,"\"Literary works\" are works, other than audiovisual works, expressed in words, numbers, or other verbal or numerical symbols or indicia, regardless of the nature of the material objects, such as books, periodicals, manuscripts, phonorecords, film, tapes, disks, or cards, in which they are embodied."],[1,"The term \"motion picture exhibition facility\" means a movie theater, screening room, or other venue that is being used primarily for the exhibition of a copyrighted motion picture, if such exhibition is open to the public or is made to an assembled group of viewers outside of a normal circle of a family and its social acquaintances."],[1,"\"Motion pictures\" are audiovisual works consisting of a series of related images which, when shown in succession, impart an impression of motion, together with accompanying sounds, if any."],[1,"To \"perform\" a work means to recite, render, play, dance, or act it, either directly or by means of any device or process or, in the case of a motion picture or other audiovisual work, to show its images in any sequence or to make the sounds accompanying it audible."],[1,"A \"performing rights society\" is an association, corporation, or other entity that licenses the public performance of nondramatic musical works on behalf of copyright owners of such works, such as the American Society of Composers, Authors and Publishers (ASCAP), Broadcast Music, Inc. (BMI), and SESAC, Inc."],[1,"\"Phonorecords\" are material objects in which sounds, other than those accompanying a motion picture or other audiovisual work, are fixed by any method now known or later developed, and from which the sounds can be perceived, reproduced, or otherwise communicated, either directly or with the aid of a machine or device. The term \"phonorecords\" includes the material object in which the sounds are first fixed."],[1,"\"Pictorial, graphic, and sculptural works\" include two-dimensional and three-dimensional works of fine, graphic, and applied art, photographs, prints and art reproductions, maps, globes, charts, diagrams, models, and technical drawings, including architectural plans. Such works shall include works of artistic craftsmanship insofar as their form but not their mechanical or utilitarian aspects are concerned; the design of a useful article, as defined in this section, shall be considered a pictorial, graphic, or sculptural work only if, and only to the extent that, such design incorporates pictorial, graphic, or sculptural features that can be identified separately from, and are capable of existing independently of, the utilitarian aspects of the article."],[1,"For purposes of section 513, a \"proprietor\" is an individual, corporation, partnership, or other entity, as the case may be, that owns an establishment or a food service or drinking establishment, except that no owner or operator of a radio or television station licensed by the Federal Communications Commission, cable system or satellite carrier, cable or satellite carrier service or programmer, provider of online services or network access or the operator of facilities therefor, telecommunications company, or any other such audio or audiovisual service or programmer now known or as may be developed in the future, commercial subscription music service, or owner or operator of any other transmission service, shall under any circumstances be deemed to be a proprietor."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§101. Definitions","tname":"Copyrights","by":{"0":"2"}},{"t":"usc","label":"17 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/17/102","subs":["(a)"],"by":{"0":"2"}},{"t":"usc","label":"17 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/17/106","stext":{"head":"§106. Exclusive rights in copyrighted works","paras":[[0,"Subject to sections 107 through 122, the owner of copyright under this title has the exclusive rights to do and to authorize any of the following:"],[1,"(1) to reproduce the copyrighted work in copies or phonorecords;"],[1,"(2) to prepare derivative works based upon the copyrighted work;"],[1,"(3) to distribute copies or phonorecords of the copyrighted work to the public by sale or other transfer of ownership, or by rental, lease, or lending;"],[1,"(4) in the case of literary, musical, dramatic, and choreographic works, pantomimes, and motion pictures and other audiovisual works, to perform the copyrighted work publicly;"],[1,"(5) in the case of literary, musical, dramatic, and choreographic works, pantomimes, and pictorial, graphic, or sculptural works, including the individual images of a motion picture or other audiovisual work, to display the copyrighted work publicly; and"],[1,"(6) in the case of sound recordings, to perform the copyrighted work publicly by means of a digital audio transmission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/106?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§106. Exclusive rights in copyrighted works","tname":"Copyrights","by":{"0":"2"}},{"t":"usc","label":"17 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/17/201","subs":["(a)","(d)"],"stext":{"head":"§201. Ownership of copyright","paras":[[0,"(a) Initial Ownership.—Copyright in a work protected under this title vests initially in the author or authors of the work. The authors of a joint work are coowners of copyright in the work."],[0,"(b) Works Made for Hire.—In the case of a work made for hire, the employer or other person for whom the work was prepared is considered the author for purposes of this title, and, unless the parties have expressly agreed otherwise in a written instrument signed by them, owns all of the rights comprised in the copyright."],[0,"(c) Contributions to Collective Works.—Copyright in each separate contribution to a collective work is distinct from copyright in the collective work as a whole, and vests initially in the author of the contribution. In the absence of an express transfer of the copyright or of any rights under it, the owner of copyright in the collective work is presumed to have acquired only the privilege of reproducing and distributing the contribution as part of that particular collective work, any revision of that collective work, and any later collective work in the same series."],[0,"(d) Transfer of Ownership.—"],[1,"(1) The ownership of a copyright may be transferred in whole or in part by any means of conveyance or by operation of law, and may be bequeathed by will or pass as personal property by the applicable laws of intestate succession."],[1,"(2) Any of the exclusive rights comprised in a copyright, including any subdivision of any of the rights specified by section 106, may be transferred as provided by clause (1) and owned separately. The owner of any particular exclusive right is entitled, to the extent of that right, to all of the protection and remedies accorded to the copyright owner by this title."],[0,"(e) Involuntary Transfer.—When an individual author's ownership of a copyright, or of any of the exclusive rights under a copyright, has not previously been transferred voluntarily by that individual author, no action by any governmental body or other official or organization purporting to seize, expropriate, transfer, or exercise rights of ownership with respect to the copyright, or any of the exclusive rights under a copyright, shall be given effect under this title, except as provided under title 11."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§201. Ownership of copyright","tname":"Copyrights","by":{"0":"2, 2"}},{"t":"usc","label":"17 U.S.C. § 302","url":"https://www.law.cornell.edu/uscode/text/17/302","subs":["(a)"],"by":{"0":"2, 14"}},{"t":"usc","label":"17 U.S.C. § 304","url":"https://www.law.cornell.edu/uscode/text/17/304","subs":["(a)"],"by":{"0":"2, 14"}},{"t":"usc","label":"17 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/17/501","subs":["(a)","(b)"],"by":{"0":"12, 12"}},{"t":"usc","label":"17 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/17/502","subs":["(a)"],"stext":{"head":"§502. Remedies for infringement: Injunctions","paras":[[0,"(a) Any court having jurisdiction of a civil action arising under this title may, subject to the provisions of section 1498 of title 28, grant temporary and final injunctions on such terms as it may deem reasonable to prevent or restrain infringement of a copyright."],[0,"(b) Any such injunction may be served anywhere in the United States on the person enjoined; it shall be operative throughout the United States and shall be enforceable, by proceedings in contempt or otherwise, by any United States court having jurisdiction of that person. The clerk of the court granting the injunction shall, when requested by any other court in which enforcement of the injunction is sought, transmit promptly to the other court a certified copy of all the papers in the case on file in such clerk's office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/502?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§502. Remedies for infringement: Injunctions","tname":"Copyrights","by":{"0":"2, 28, 2"}},{"t":"usc","label":"17 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/17/503","stext":{"head":"§503. Remedies for infringement: Impounding and disposition of infringing articles","paras":[[0,"(a)(1) At any time while an action under this title is pending, the court may order the impounding, on such terms as it may deem reasonable—"],[1,"(A) of all copies or phonorecords claimed to have been made or used in violation of the exclusive right of the copyright owner;"],[1,"(B) of all plates, molds, matrices, masters, tapes, film negatives, or other articles by means of which such copies or phonorecords may be reproduced; and"],[1,"(C) of records documenting the manufacture, sale, or receipt of things involved in any such violation, provided that any records seized under this subparagraph shall be taken into the custody of the court."],[0,"(2) For impoundments of records ordered under paragraph (1)(C), the court shall enter an appropriate protective order with respect to discovery and use of any records or information that has been impounded. The protective order shall provide for appropriate procedures to ensure that confidential, private, proprietary, or privileged information contained in such records is not improperly disclosed or used."],[0,"(3) The relevant provisions of paragraphs (2) through (11) of section 34(d) of the Trademark Act (15 U.S.C. 1116(d)(2) through (11)) shall extend to any impoundment of records ordered under paragraph (1)(C) that is based upon an ex parte application, notwithstanding the provisions of rule 65 of the Federal Rules of Civil Procedure. Any references in paragraphs (2) through (11) of section 34(d) of the Trademark Act to section 32 of such Act shall be read as references to section 501 of this title, and references to use of a counterfeit mark in connection with the sale, offering for sale, or distribution of goods or services shall be read as references to infringement of a copyright."],[0,"(b) As part of a final judgment or decree, the court may order the destruction or other reasonable disposition of all copies or phonorecords found to have been made or used in violation of the copyright owner's exclusive rights, and of all plates, molds, matrices, masters, tapes, film negatives, or other articles by means of which such copies or phonorecords may be reproduced."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/503?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§503. Remedies for infringement: Impounding and disposition of infringing articles","tname":"Copyrights","by":{"0":"3"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","subs":["(a)(1)","(b)","(c)"],"stext":{"head":"§504. Remedies for infringement: Damages and profits","paras":[[0,"(a) In General.—Except as otherwise provided by this title, an infringer of copyright is liable for either—"],[1,"(1) the copyright owner's actual damages and any additional profits of the infringer, as provided by subsection (b); or"],[1,"(2) statutory damages, as provided by subsection (c)."],[0,"(b) Actual Damages and Profits.—The copyright owner is entitled to recover the actual damages suffered by him or her as a result of the infringement, and any profits of the infringer that are attributable to the infringement and are not taken into account in computing the actual damages. In establishing the infringer's profits, the copyright owner is required to present proof only of the infringer's gross revenue, and the infringer is required to prove his or her deductible expenses and the elements of profit attributable to factors other than the copyrighted work."],[0,"(c) Statutory Damages.—"],[1,"(1) Except as provided by clause (2) of this subsection, the copyright owner may elect, at any time before final judgment is rendered, to recover, instead of actual damages and profits, an award of statutory damages for all infringements involved in the action, with respect to any one work, for which any one infringer is liable individually, or for which any two or more infringers are liable jointly and severally, in a sum of not less than $750 or more than $30,000 as the court considers just. For the purposes of this subsection, all the parts of a compilation or derivative work constitute one work."],[1,"(2) In a case where the copyright owner sustains the burden of proving, and the court finds, that infringement was committed willfully, the court in its discretion may increase the award of statutory damages to a sum of not more than $150,000. In a case where the infringer sustains the burden of proving, and the court finds, that such infringer was not aware and had no reason to believe that his or her acts constituted an infringement of copyright, the court in its discretion may reduce the award of statutory damages to a sum of not less than $200. The court shall remit statutory damages in any case where an infringer believed and had reasonable grounds for believing that his or her use of the copyrighted work was a fair use under section 107, if the infringer was: (i) an employee or agent of a nonprofit educational institution, library, or archives acting within the scope of his or her employment who, or such institution, library, or archives itself, which infringed by reproducing the work in copies or phonorecords; or (ii) a public broadcasting entity which or a person who, as a regular part of the nonprofit activities of a public broadcasting entity (as defined in section 118(f)) infringed by performing a published nondramatic literary work or by reproducing a transmission program embodying a performance of such a work."],[1,"(3)(A) In a case of infringement, it shall be a rebuttable presumption that the infringement was committed willfully for purposes of determining relief if the violator, or a person acting in concert with the violator, knowingly provided or knowingly caused to be provided materially false contact information to a domain name registrar, domain name registry, or other domain name registration authority in registering, maintaining, or renewing a domain name used in connection with the infringement."],[1,"(B) Nothing in this paragraph limits what may be considered willful infringement under this subsection."],[1,"(C) For purposes of this paragraph, the term \"domain name\" has the meaning given that term in section 45 of the Act entitled \"An Act to provide for the registration and protection of trademarks used in commerce, to carry out the provisions of certain international conventions, and for other purposes\" approved July 5, 1946 (commonly referred to as the \"Trademark Act of 1946\"; 15 U.S.C. 1127)."],[0,"(d) Additional Damages in Certain Cases.—In any case in which the court finds that a defendant proprietor of an establishment who claims as a defense that its activities were exempt under section 110(5) did not have reasonable grounds to believe that its use of a copyrighted work was exempt under such section, the plaintiff shall be entitled to, in addition to any award of damages under this section, an additional award of two times the amount of the license fee that the proprietor of the establishment concerned should have paid the plaintiff for such use during the preceding period of up to 3 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/504?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§504. Remedies for infringement: Damages and profits","tname":"Copyrights","by":{"0":"3, 19, 20, 29, 3"}},{"t":"usc","label":"17 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/17/507","subs":["(b)"],"stext":{"head":"§507. Limitations on actions","paras":[[0,"(a) Criminal Proceedings.—Except as expressly provided otherwise in this title, no criminal proceeding shall be maintained under the provisions of this title unless it is commenced within 5 years after the cause of action arose."],[0,"(b) Civil Actions.—No civil action shall be maintained under the provisions of this title unless it is commenced within three years after the claim accrued."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/507?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§507. Limitations on actions","tname":"Copyrights","by":{"0":"passim"}},{"t":"usc","label":"17 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/17/701","by":{"0":"1"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(b)(9)"],"by":{"0":"25"}},{"t":"usc","label":"35 U.S.C. § 286","url":"https://www.law.cornell.edu/uscode/text/35/286","stext":{"head":"§286. Time limitation on damages","paras":[[0,"Except as otherwise provided by law, no recovery shall be had for any infringement committed more than six years prior to the filing of the complaint or counterclaim for infringement in the action."],[0,"In the case of claims against the United States Government for use of a patented invention, the period before bringing suit, up to six years, between the date of receipt of a written claim for compensation by the department or agency of the Government having authority to settle such claim, and the date of mailing by the Government of a notice to the claimant that his claim has been denied shall not be counted as part of the period referred to in the preceding paragraph."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/286?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§286. Time limitation on damages","tname":"Patents","by":{"0":"25"}}]};